  }
  const ordinalWord=number=>number===1?"prima":number===2?"seconda":number===3?"terza":number===4?"quarta":`${number}ª`;
  function archiveCard(data,number,matchById){
    const stats=archiveStats(data,matchById);
    const finished=stats.archiveStake>0;
    const detail=`<span class="betting-archive-performance"><span><small>Successo</small><strong>${metric(finished?stats.archiveSuccessPct:null,pct,"%")}</strong></span><span><small>Guadagno</small><strong>${finished&&stats.archiveProfitPct>0?"+":""}${metric(finished?stats.archiveProfitPct:null,pct,"%")}</strong></span></span>`;
    const palette=["#123e85","#9b1c31","#0f766e","#7c3aed","#b45309","#0369a1"];
