    return `<a class="betting-archive-card team-directory-card team-flip-card" href="schedina.html?giornata=${number}" aria-label="Apri le schedine della ${ordinalWord(number)} giornata" style="--team-primary:${colors[number]};--team-secondary:#06152b"><span class="team-flip-inner"><span class="team-flip-face team-flip-front betting-archive-card-front"><span class="betting-archive-number">${number}</span></span><span class="team-flip-face team-flip-back betting-archive-card-back"><strong>${number}ª giornata</strong>${detail}</span></span></a>`;
  }

  function championsArchiveCard(data,number=1){
    const selections=(data.slips?data.slips.flatMap(slip=>slip.legs):data.fixtures.flatMap(fixture=>fixture.selections||[])).filter(leg=>number!==3||hasVerifiedPlayableQuote(leg));
    const stats=archiveStats({matchday:number,slips:[{legs:selections}]},null,leg=>leg.settlement||{status:"pending"});
    const verified=null; // Public economics always follow the visible filtered contracts.
    const wins=verified?verified.green:stats.archiveWins;
    const total=verified?verified.considered:stats.archiveStake;
    const decided=verified?verified.green+verified.red:stats.archiveStake;
    const success=decided?wins/decided*100:null;
    const profit=verified?verified.roiPct:total?stats.archiveProfitPct:null;
    const performance=`<span class="betting-archive-performance"><span><small>Successo</small><strong>${metric(success,pct,"%")}</strong></span><span><small>Guadagno</small><strong>${profit>0?"+":""}${metric(profit,pct,"%")}</strong></span></span>`;
    return `<a class="betting-archive-card betting-archive-card--champions team-directory-card team-flip-card" data-champions-matchday="${number}" href="schedina.html?competizione=champions&amp;giornata=${number}" aria-label="Apri le schedine Champions League della ${ordinalWord(number)} giornata" style="--team-primary:#0756c9;--team-secondary:#02183f"><span class="team-flip-inner"><span class="team-flip-face team-flip-front betting-archive-card-front betting-champions-front" style="color:#fff"><span class="betting-archive-number">CL${number}</span></span><span class="team-flip-face team-flip-back betting-archive-card-back"><strong>${number}ª giornata</strong>${performance}</span></span></a>`;
  }

