  }

  function pilotReadingDetail(fixture,pilot,backtest,squads,branding,h2h,motivationEntry,styleProfiles,attackByTeam,surpriseEntry,playerMarketEntry,playerMarketDataset,md2MarketEntry,md2SchedinaFixture){
