    const h2hPanel=h2hRows?`<details class="section reading-h2h-section champions-reading-h2h champions-reading-history-disclosure" id="champions-history"><summary><span><small>Storico ufficiale · UEFA</small><strong>Precedenti</strong></span><span>${h2hFixture.meetings}/${h2hFixture.maximumMeetings||4} precedenti · competizioni UEFA</span></summary><div class="reading-h2h-list">${h2hRows}</div></details>`:"";
