    const markup=controller.championsWorkspaceMarkup(workspace,fixtureId);
    if(section){
      target.insertAdjacentHTML('beforeend',`<details class="rd-disclosure rd-champions-catalog"><summary>${matchday===3?'Schedina personale e dettagli dei pronostici':'Dettagli dei pronostici e MyCombo'}</summary>${markup}</details>`);
      target.querySelectorAll('.betting-round-page > .rd-section-heading,.betting-round-page > .betting-round-heading').forEach(n=>n.remove());
    }else target.insertAdjacentHTML('beforeend',markup);
    const store=controller.mountChampionsWorkspace(workspace);
    if(section){
      const [{createReadingView},{installForecasts},{sharedForecastsForMatch}]=await Promise.all([import('./reading-detail/view-model.mjs?v=20261022-assets-v1'),import('./reading-detail/forecasts.mjs?v=20261104-champions-results'),import('./shared-forecast-contract.mjs?v=20261102-champions-no-draw')]);
